INSERT INTO book_versions(book_id,version,title,author,genre,rights_status,rights_basis,content_hash,object_key) VALUES
 ('diary-of-madman', '1', 'Записки сумасшедшего', 'Николай Гоголь', 'Классика', 'approved', 'Русский оригинал — общественное достояние. Источник текста: Интернет-библиотека Алексея Комарова. Электронная публикация Интернет-библиотеки Алексея Комарова; печатное издание на странице источника не указано. Страницы источника разрешают свободное использование произведения. Включён полный литературный текст выбранной публикации, без навигации, оформления, скриптов, редакционных сносок и переводов в сносках; пробелы нормализованы, курсив приведён к обычному тексту, строки эпиграфов соединены пробелами. Источники всех страниц и SHA-256 закреплены отдельно. Обложка: Титульный лист печатного собрания «Сочинения Н. В. Гоголя», 11-е изд., ред. Н. С. Тихонравова, т. 3, А. Ф. Маркс, Санкт-Петербург, 1893. Страница 10 скана Wikimedia Commons (Public Domain), JPEG без дальнейших изменений. Другое издание, чем источник текста.', '1ad45627199293511ef7e874caf335eac9d8dc46cea2140ed19c83edb794b0e4', '/books/diary-of-madman.json'),
